  !/grid|protector|colander|dishpan|dish tub|washing up|tub|kit/i.test(p.title) &&
  /sink/i.test(p.title)
);
return JSON.stringify({all: allProducts.length, doubleBowlSinks: doubleBowl, otherSinks}, null, 2);
"}

