function getAllProducts() {
  const items = document.querySelectorAll('[data-component-type="s-search-result"]');
  const products = [];
  items.forEach((item, index) => {
    const titleEl = item.querySelector('h2');
    const title = titleEl ? titleEl.textContent.trim() : '';
    const priceEl = item.querySelector('.a-price .a-offscreen');
    const price = priceEl ? priceEl.textContent.trim() : '';
    const linkEl = item.querySelector('h2 a');
    const href = linkEl ? linkEl.getAttribute('href') : '';
    const asin = item.getAttribute('data-asin') || '';
    products.push({index, asin, title, price, href: href.substring(0, 80)});
  });
  return products;
}
const allProducts = getAllProducts();
const doubleBowl = allProducts.filter(p => 
  /double.{0,5}bowl/i.test(p.title) && !/single/i.test(p.title) && 
  !/grid|protector|colander|dishpan|bowl|tub|basin|kit|colander/i.test(p.title)
);
